head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.vISUR_CD21301 = "";
scwin.vISUR_NM21301 = "";
scwin.add_gb21301 = "";

/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    await scwin.gform_onload();
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

/**
 * @method
 * @name init
 * @description 화면 초기화 — 파라미터 수신·기본값·컴포넌트 초기 설정(onpageload 에서 순차 호출)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init = async function() {
    txb_param1.hide();
    txb_param2.hide();
    txb_KEY.hide();
    txb_PREPAY_NO.hide();
    $c.cm.PanelToGroupBox(panel_2);

    // fn_com_isur(txb_ISUR_CD, txb_COM_NM);

    const vTemp = frame.FrameID;
    const Temp2 = vTemp.split("|")[1];
    const vISUR_CD = Temp2.split("=")[1]; // ISUR_CD

    if (vISUR_CD !== "") {
        // 기존 발행기관

        // 발행기관 비활성화
        txb_ISUR_CD.setReadOnly(true);
        txb_COM_NM.setReadOnly(true);
        txb_ISUR_CD.setValue(vISUR_CD);
        txb_COM_NM.setValue($c.frame.path("../").txb_COM_NM2.getValue());

        // 전역변수 세팅
        scwin.vISUR_CD21301 = txb_ISUR_CD.getValue();
        scwin.vISUR_NM21301 = txb_COM_NM.getValue();
        scwin.add_gb21301 = "SEARCH";

        // 단순조회
        await scwin.listPrepayChg("NODATA", "NODATA");
    }
};

/**
 * @method
 * @name initDs
 * @description 데이터셋 초기화.
 * @returns {void}
 * @hidden N
 */
scwin.initDs = function() {
    dts_PayInfo.removeAll();
};
scwin.arrPar = new Array();

/**
 * @method
 * @name getParam
 * @description 전달값을 설정한다.
 * @param {Array} arrPar 팝업 파라미터 배열(참조 채움)
 * @returns {void}
 * @hidden N
 */
scwin.getParam = function(arrPar) {
    scwin.arrPar[0] = txb_param1.getValue(); // 발행기관코드
    scwin.arrPar[1] = txb_param2.getValue(); // 발행기관코드명

    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    //
    // ********************************************************************
    scwin.arrPar, length;
};

/**
 * @method
 * @name listPrepayChg
 * @description 선납잔액 조회
 * @param {String} ISUR_CD ISUR_CD
 * @param {String} COM_NM COM_NM
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.listPrepayChg = async function(ISUR_CD, COM_NM) {
    // 데이터셋 초기화
    // fn_InitDs();

    // 입력 후 재조회를 위해 세팅
    // if (add_gb21301 == "SEARCH") {
    if (ISUR_CD === "NODATA") {
        ISUR_CD = scwin.vISUR_CD21301;
        txb_ISUR_CD.setValue(scwin.vISUR_CD21301);
        txb_COM_NM.setValue(scwin.vISUR_NM21301);
    } else {
        // 전역변수 세팅
        scwin.vISUR_CD21301 = ISUR_CD;
        // alert("전역변수vISUR_CD21301 :"+vISUR_CD21301);
        scwin.vISUR_NM21301 = COM_NM;
    }

    // Lodaing~~~ 표시

    // 선납잔액 조회
    url += "&SCREN_ID=" + "ULDINS21301.xml";
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    if (ISUR_CD === "NODATA") {
        url += "&ISUR_CD=" + txb_ISUR_CD.getValue();
    } else {
        url += "&ISUR_CD=" + ISUR_CD;
    }
    const sbmOptions = {
        id : "sbm_dts_detail",
        action : "/PrepayInfoAction.do",
        ref : "",
        target : "dts_detail=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name listPrepayChg3
 * @description 선납금 조회
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.listPrepayChg3 = async function() {
    // 선납금등록내역 Grid 조회
    url += "&ISUR_CD=" + txb_ISUR_CD.getValue();
    url += "&SDATE=" + "";
    url += "&EDATE=" + "";
    url += "&SCREN_ID=" + "ULDINS21301.xml";
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    const sbmOptions = {
        id : "sbm_dts_PayInfo",
        action : "/PrepayInfoAction.do",
        ref : "",
        target : "dts_PayInfo=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name listPrepayChgAppl
 * @description list Prepay Chg Appl 처리
 * @returns {void}
 * @hidden N
 */
scwin.listPrepayChgAppl = function() {
    // alert(getObjectValue(txb_ISUR_CD));

    let url = "/listingCommon.do?SCREN_ID=" + "ULDINS21301.xml" + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listGeneralForDynamicName" + "&outputMessageId=STDCDREQINFO_LIST_OUT" + "&service=krx.lds.ins.listingcommon.services.ListingCommonApp" + "&queryId=lds.ins.stdcd.select.listTbldBscdaplInquiry" + "&{P}ISUR_CD=" + txb_ISUR_CD.getValue() + // 발행기관코드
        "&{P}STD_CD_GRNT_FEE_PROCS_STAT_CD=2" + // 납부구분 건납
        "&{P}STD_CD_APPL_CONTN_TP_CD="; // 채권 03425	표준코드신청내용구분코드
    dts_ApplInfo.DataID = encodeURI(url);
    dts_ApplInfo.reset();

};

/**
 * @method
 * @name ins_PrepayChg
 * @description 선납금 전환 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.ins_PrepayChg = async function() {
    // 선납금전환 대상을 점검
    if (await scwin.chkValid() === false) return;
    const msg = $c.stf.getMessageParam("MSG-A006", "선납금 전환");
    const res = window.confirm(msg);
    if (res) {
        // 선택된 Row만 서버로 전송..
        scwin.setTransData();
        trs_Return.KeyName = "toinb_dataid4";
        // [전환검토] trs_Return.Parameters → 동적 파라미터(필요 시 sbmOptions 에 반영)
        // const sbmParams = {
        //     EMP_NO : js_emp_no,
        //     EMP_NM : js_emp_nm,
        //     EMAIL : js_email
        // };
        const sbmOptions = {
            id : "sbm_trs_Return",
            action : "/PrepayInfoAction.do",
            ref : "dts_ApplInfo",
            target : "trs_Return=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
    }
};

/**
 * @method
 * @name chkValid
 * @description 선납금전환 대상을 점검
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.chkValid = async function() {
    let cnt = 0;
    let cnt2 = 0;
    let cnt3 = 0;
    const visurCd = "";
    const vDepDd = "";
    for (let nRow = 1; nRow <= dts_ApplInfo.getRowCount(); nRow++) {
        if (dts_ApplInfo.getCellData(nRow, "CHK") === "T") {
            cnt++;
            if ("2" !== (dts_ApplInfo.getCellData(nRow, "STD_CD_GRNT_FEE_PROCS_STAT_CD"))) {
                cnt2++;
            }
            if ("0" !== (dts_ApplInfo.getCellData(nRow, "DEPO_AMT_FMT"))) {
                cnt3++;
            }
        }
    }
    // alert("cnt: " +cnt);
    if (Number(cnt) === 0) {
        await $c.win.alert("선납금전환 대상을 체크하세요.");
        return false;
    }
    if (Number(cnt2) > 0) {
        await $c.win.alert("선납금전환은 납입구분이 [건납]인 경우에만 가능합니다.");
        return false;
    }
    if (Number(cnt3) > 0) {
        await $c.win.alert("이미 입금된 건은 선납으로 전환 할 수 없습니다.");
        return false;
    }
    return true;
};

/**
 * @method
 * @name setTransData
 * @description 선택된 row의 값을 강제로 변경.. 이렇게 하면 변경된 row만 서버로 전송될것 같아서..
 * @returns {void}
 * @hidden N
 */
scwin.setTransData = function() {
    let nRow = dts_ApplInfo.getRowPosition();
    dts_ApplInfo.setCellData(nRow, "CHK", "T");
};

/**
 * @method
 * @name setCheckBox
 * @description 그리드 체크박스 전체선택 또는 전체선택 해제
 * @param {*} grdObj grdObj
 * @param {*} dtsObj dtsObj
 * @param {*} bCheck bCheck
 * @returns {void}
 * @hidden N
 */
scwin.setCheckBox = function(grdObj, dtsObj, bCheck) {
    let vcd = "";
    if (bCheck === '1') {
        vcd = "T";
    } else {
        vcd = "F";
    }
    grdObj.setBroadcast(false);
    for (let i = 1; i <= dtsObj.getRowCount(); i++) {
        dtsObj.setCellData(i, "CHK", vcd);
    }
    grdObj.setBroadcast(true);
};

/**
 * @method
 * @name chkClickValid
 * @description 선납전환 체크대상을 점검
 * @param {*} col col
 * @param {*} colid colid
 * @param {*} bCheck bCheck
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.chkClickValid = async function(col, colid, bCheck) {
    // alert("col : " + col);
    // alert(" colid: " + colid);
    // alert(" bCheck: " + bCheck);

    if (bCheck === '1') {
        // 체크선택
        if ("2" !== (dts_ApplInfo.getCellData(col, "STD_CD_GRNT_FEE_PROCS_STAT_CD")) || "0" !== (dts_ApplInfo.getCellData(col, "DEPO_AMT_FMT"))) {
            await $c.win.alert("이미 입금된 건은 선납으로 전환 할 수 없습니다.");
            dts_ApplInfo.setCellData(col, "CHK", "0");
            return false;
        }
    }
};

/**
 * @method
 * @name grd_ApplInfo_CanColumnPosChange
 * @description grd Appl Info Can Column Pos Change 처리
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {void}
 * @hidden N
 */
scwin.grd_ApplInfo_CanColumnPosChange = function(row, colid) {
    return true;
};

/**
 * @method
 * @name gform_onload
 * @description gform onload 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.gform_onload = async function() {
    await scwin.init();
};

/**
 * @method
 * @name dts_detail_OnLoadError
 * @description dts_detail 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_detail_OnLoadError = async function() {
    await $c.win.alert(dts_detail);
};

/**
 * @method
 * @name dts_detail_OnLoadCompleted
 * @description dts_detail 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_detail_OnLoadCompleted = async function() {
    await scwin.listPrepayChg3(); // 기존선급금 존재기관

};

/**
 * @method
 * @name dts_PayInfo_OnLoadError
 * @description dts_PayInfo 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_PayInfo_OnLoadError = async function() {
    await $c.win.alert(dts_PayInfo);
};

/**
 * @method
 * @name dts_PayInfo_OnLoadCompleted
 * @description dts_PayInfo 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_PayInfo_OnLoadCompleted = async function(rowcount) {
    if (dts_PayInfo.errorMsg) {
        await $c.win.alert(dts_PayInfo.errorMsg);
    } else {
        if (txb_PREPAY_BAL.getValue() === "") {
            txb_TotalCnt.setValue("총 0건"); // 신규

        } else {
            txb_TotalCnt.setValue("총 " + rowcount + "건"); // 기존선급금 존재기관

        }
    }

    // 데이터가 없는 경우
    if (rowcount === 0) {
        fn_CtrlBtn_temp("no_data");
    }
    scwin.listPrepayChgAppl();
};

/**
 * @method
 * @name dts_ApplInfo_OnLoadCompleted
 * @description dts_ApplInfo 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_ApplInfo_OnLoadCompleted = async function(rowcount) {
    if (dts_ApplInfo.errorMsg) {
        await $c.win.alert(dts_ApplInfo.errorMsg);
        btn_PrepayChg.setDisabled(true);
        btn_PrepayChg.setBackgroundImage("../img/ins/btn_prepay_chg_d.png");
    } else {
        txb_TotalCnt_Appl.setValue("총 " + rowcount + "건"); // 선급금 전환대상
        btn_PrepayChg.setDisabled(false);
        btn_PrepayChg.setBackgroundImage("../img/ins/btn_prepay_chg.png");
    }

    // 데이터가 없는 경우
    if (rowcount === 0) {
        fn_CtrlBtn_temp("no_data");
        btn_PrepayChg.setDisabled(true);
        btn_PrepayChg.setBackgroundImage("../img/ins/btn_prepay_chg_d.png");
    }
};

/**
 * @method
 * @name MxDataSet_com_isur_OnFilter
 * @description Mx Data Set com isur On Filter 처리
 * @param {Number} row 행 인덱스
 * @returns {void}
 * @hidden N
 */
scwin.MxDataSet_com_isur_OnFilter = function(row) {
    if (skw !== "" && foColum === "1") {
        f1 = MxDataSet_com_isur.getCellData(row, "COM_ABBRV");
        f2 = MxDataSet_com_isur.getCellData(row, "OLD_COM_ABBRV");
        if (f1.indexOf(skw) !== -1 || f2.indexOf(skw) !== -1) return true;

        else return false;
    } else {
        return true;
    }
};

/**
 * @method
 * @name btn_PrepayChg_onclick
 * @description 「선납금전환」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_PrepayChg_onclick = async function() {
    await scwin.ins_PrepayChg();
};

/**
 * @method
 * @name grd_ApplInfo_onheadcheckclick
 * @description grd_ApplInfo onheadcheckclick 이벤트
 * @param {*} col col
 * @param {*} colid colid
 * @param {*} bCheck bCheck
 * @returns {void}
 * @hidden N
 */
scwin.grd_ApplInfo_onheadcheckclick = function(col, colid, bCheck) {
    scwin.setCheckBox(grd_ApplInfo, dts_ApplInfo, bCheck);
};

/**
 * @method
 * @name grd_ApplInfo_oncheckclick
 * @description grd_ApplInfo oncheckclick 이벤트
 * @param {*} col col
 * @param {*} colid colid
 * @param {*} bCheck bCheck
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_ApplInfo_oncheckclick = async function(col, colid, bCheck) {
    await scwin.chkClickValid(col, colid, bCheck);
};

/**
 * @method
 * @name trs_Return_OnFail
 * @description Return On Fail 처리
 * @returns {void}
 * @hidden N
 */
scwin.trs_Return_OnFail = function() {
    alert_tr_error(trs_Return);
};

/**
 * @method
 * @name trs_Return_OnSuccess
 * @description Return On Success 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_Return_OnSuccess = async function() {
    await $c.win.alert($c.stf.getMessageParam("MSG-0001"));
    scwin.listPrepayChgAppl();
};
